#!/usr/bin/env python3
# Generated by Gemini 3.8 Flash
"""
Adds the yaml-language-server schema comment to the top of YAML files.
"""

import argparse
import re
import sys
from pathlib import Path

DEFAULT_SCHEMA_URL = (
    "https://cdn.jsdelivr.net/gh/INTI-CMNB/KiBot@master/docs/kibot_schema.json"
)

# Regex matching any existing yaml-language-server $schema directive
SCHEMA_PATTERN = re.compile(
    r"^#\s*yaml-language-server:\s*\$schema=.*$", re.IGNORECASE
)


def process_file(
    path: Path, schema_url: str, force: bool = False, dry_run: bool = False
) -> bool:
    target_header = f"# yaml-language-server: $schema={schema_url}\n"

    try:
        content = path.read_text(encoding="utf-8")
    except Exception as e:
        print(f"Error reading {path}: {e}", file=sys.stderr)
        return False

    lines = content.splitlines(keepends=True)

    # Check if the file is empty
    if not lines:
        new_content = target_header
    else:
        first_line = lines[0].strip()

        # Check if already present and matches target
        if SCHEMA_PATTERN.match(first_line):
            if lines[0].strip() == target_header.strip():
                print(f"Skipping (already up to date): {path}")
                return False
            elif not force:
                print(
                    f"Skipping (schema already set, use --force to overwrite): {path}"
                )
                return False
            else:
                # Replace existing schema header
                lines[0] = target_header
                new_content = "".join(lines)
        else:
            # Prepend the new header
            new_content = target_header + content

    if dry_run:
        print(f"[DRY-RUN] Would update: {path}")
        return True

    try:
        path.write_text(new_content, encoding="utf-8")
        print(f"Updated: {path}")
        return True
    except Exception as e:
        print(f"Error writing {path}: {e}", file=sys.stderr)
        return False


def main():
    parser = argparse.ArgumentParser(
        description="Prepend yaml-language-server $schema header to YAML files."
    )
    parser.add_argument(
        "files",
        nargs="+",
        type=Path,
        help="One or more YAML files to update.",
    )
    parser.add_argument(
        "-s",
        "--schema",
        default=DEFAULT_SCHEMA_URL,
        help=f"Schema URL to use (default: {DEFAULT_SCHEMA_URL})",
    )
    parser.add_argument(
        "-f",
        "--force",
        action="store_true",
        help="Overwrite existing schema header if a different one is found.",
    )
    parser.add_argument(
        "-n",
        "--dry-run",
        action="store_true",
        help="Show what would be changed without writing to disk.",
    )

    args = parser.parse_args()

    for file_path in args.files:
        if not file_path.is_file():
            print(f"Not a file, skipping: {file_path}", file=sys.stderr)
            continue
        process_file(
            file_path,
            schema_url=args.schema,
            force=args.force,
            dry_run=args.dry_run,
        )


if __name__ == "__main__":
    main()
